<script setup lang="ts">
import { onMounted, ref } from 'vue'
import AppShell from '../components/product/AppShell.vue'
import EmptyState from '../components/product/EmptyState.vue'
import http, { ApiError } from '../utils/http'
interface DocumentItem { id: number; original_filename: string; course: string; size: number; status: string; chunk_count: number }
interface UserItem { id: number; username: string; role: string }
const tab = ref<'knowledge'|'users'|'system'>('knowledge'); const documents = ref<DocumentItem[]>([]); const users = ref<UserItem[]>([]); const denied = ref(false); const uploading = ref(false); const uploadProgress = ref(0); const course = ref('Python'); const toast = ref(''); const error = ref(''); const fileInput = ref<HTMLInputElement>()
async function load() { const [docs, people] = await Promise.allSettled([http.get('/api/knowledge/list'), http.get('/api/auth/users')]); if (docs.status === 'fulfilled') documents.value = docs.value.data; if (people.status === 'fulfilled') users.value = people.value.data; else denied.value = people.reason instanceof ApiError && people.reason.status === 403 }
async function upload(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; error.value = ''; if (file.size > 20 * 1024 * 1024) { error.value = '文件不能超过 20MB，已在上传前拦截'; return } const body = new FormData(); body.append('file', file); body.append('course', course.value); uploading.value = true; try { const response = await http.post('/api/knowledge/upload', body, { timeout: 120000, onUploadProgress: (progress) => uploadProgress.value = progress.total ? Math.round(progress.loaded / progress.total * 100) : 0 }); documents.value.unshift(response.data); toast.value = '知识文档上传并索引成功' } catch (cause) { error.value = cause instanceof Error ? cause.message : '上传失败' } finally { uploading.value = false; uploadProgress.value = 0; if (fileInput.value) fileInput.value.value = '' } }
onMounted(load)
</script>
<template><AppShell><section class="page-header"><div><span class="eyebrow">系统运营中心</span><h1>管理后台</h1><p>管理课程知识、用户与系统连接状态。</p></div></section><div class="admin-tabs"><button :class="{ active: tab === 'knowledge' }" @click="tab = 'knowledge'">知识库</button><button :class="{ active: tab === 'users' }" @click="tab = 'users'">用户列表</button><button :class="{ active: tab === 'system' }" @click="tab = 'system'">系统配置</button></div><div v-if="toast" class="success-toast" @animationend="toast = ''">{{ toast }}</div><div v-if="error" class="error-banner form-shake">{{ error }}</div><section v-if="tab === 'knowledge'" class="admin-panel"><div class="upload-zone"><img src="/assets/mascot-thinking.png" alt="" loading="lazy" /><div><h2>{{ uploading ? `正在上传 ${uploadProgress}%` : '上传课程知识文档' }}</h2><p>支持 PDF、DOCX、TXT、Markdown，单个文件最大 20MB。</p><label>课程名称<input v-model="course" /></label><input ref="fileInput" type="file" accept=".pdf,.docx,.txt,.md" :disabled="uploading" @change="upload" /></div></div><EmptyState v-if="!documents.length" title="知识库还是空的" description="上传第一份课程资料后，AI 回答会自动检索并引用它。" /><div v-else class="data-table"><div class="table-row head"><span>文件</span><span>课程</span><span>切片</span><span>状态</span></div><div v-for="doc in documents" :key="doc.id" class="table-row"><strong>{{ doc.original_filename }}</strong><span>{{ doc.course }}</span><span>{{ doc.chunk_count }}</span><span class="status-pill">{{ doc.status }}</span></div></div></section><section v-else-if="tab === 'users'" class="admin-panel"><EmptyState v-if="denied" title="需要管理员权限" description="当前账号可上传自己的知识文档，但用户列表仅向管理员开放。" image="/assets/mascot-error.png" /><div v-else class="data-table"><div class="table-row head"><span>用户 ID</span><span>用户名</span><span>角色</span><span>状态</span></div><div v-for="item in users" :key="item.id" class="table-row"><strong>#{{ item.id }}</strong><span>{{ item.username }}</span><span>{{ item.role }}</span><span class="status-pill">正常</span></div></div></section><section v-else class="admin-panel system-grid"><article><span class="live-dot" /><div><h2>FastAPI 服务</h2><p>接口与鉴权已连接</p></div></article><article><span class="live-dot" /><div><h2>讯飞星火</h2><p>失败时返回真实错误，不启用假数据</p></div></article><article><span class="live-dot" /><div><h2>向量知识库</h2><p>空库时自动降级为通用回答</p></div></article></section></AppShell></template>
